import{_ as e,o as r,c as a,ag as d}from"./chunks/framework.DMXcdKmJ.js";const p=JSON.parse('{"title":"连接 PostgreSQL","description":"配置外部 PostgreSQL 的数据库与 Schema，测试并保存连接，再核对查询和输出。","frontmatter":{"title":"连接 PostgreSQL","description":"配置外部 PostgreSQL 的数据库与 Schema，测试并保存连接，再核对查询和输出。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/postgresql.md","filePath":"zh/使用指南/连接PostgreSQL.md"}'),o={name:"zh/guide/postgresql.md"};function s(n,t,h,i,l,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="连接-postgresql" tabindex="-1">连接 PostgreSQL <a class="header-anchor" href="#连接-postgresql" aria-label="Permalink to &quot;连接 PostgreSQL&quot;">​</a></h1><p>这是外部 PostgreSQL 接入，不是要求使用者直接登录平台内部数据库。先准备服务地址、业务库、Schema、专用账号及 TLS 要求，并确认平台开发环境具有网络访问条件。</p><h2 id="_1-填写连接" tabindex="-1">1. 填写连接 <a class="header-anchor" href="#_1-填写连接" aria-label="Permalink to &quot;1. 填写连接&quot;">​</a></h2><p>进入 <strong>“数据中心” → “接入源” → “新建连接”</strong>，选择 <strong>“PostgreSQL”</strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>怎样填写</th></tr></thead><tbody><tr><td>连接名称</td><td>便于团队识别的业务用途</td></tr><tr><td>主机地址、端口</td><td>服务的实际地址；默认端口 5432</td></tr><tr><td>数据库名</td><td>账号获准访问的实际数据库</td></tr><tr><td>Schema</td><td>按业务表所在位置填写，默认 public；它不是另一台服务器或另一个数据库</td></tr><tr><td>用户名、密码</td><td>专用数据库账号，不因默认提示 postgres 就共用超级账号</td></tr><tr><td>SSL/TLS 配置</td><td>与服务端要求匹配，按需要提供和核验证书</td></tr><tr><td>其他连接参数</td><td>连接超时、查询超时和连接数按数据库负责人的要求设置</td></tr></tbody></table><h2 id="_2-测试、保存和核对" tabindex="-1">2. 测试、保存和核对 <a class="header-anchor" href="#_2-测试、保存和核对" aria-label="Permalink to &quot;2. 测试、保存和核对&quot;">​</a></h2><p>点击 <strong>“测试连接”</strong>，检查具体结果；成功后点击 <strong>“创建连接”</strong>。回列表核对，再打开连接工作台。</p><p>能连上但看不到表时，先核对数据库、Schema 和权限，不立即新建另一份连接。证书错误按证书链和主机名处理，不直接关闭校验。</p><h2 id="_3-开始查询" tabindex="-1">3. 开始查询 <a class="header-anchor" href="#_3-开始查询" aria-label="Permalink to &quot;3. 开始查询&quot;">​</a></h2><p>在工作台打开表或已保存查询；新任务使用 <strong>“新建查询”</strong>。运行前核对 SQL 与业务库，准备数据点时检查“输出配置”，再使用 <strong>“保存并生成数据点”</strong>，不要只点普通保存。详细步骤见<a href="/induframe-docs/zh/guide/sql-datapoints.html">SQL 数据点指南</a>。</p><p>Schema、表名和大小写应以数据库实际结构为准，不直接套用其他数据库的 SQL。</p><p>下一步：<a href="/induframe-docs/zh/guide/datapoints.html">查看数据点</a>。通用编辑、凭据保留和删除前检查见<a href="/induframe-docs/zh/guide/access-sources.html">管理接入源</a>。</p>',12)])])}const _=e(o,[["render",s]]);export{p as __pageData,_ as default};
